using JoshOlson.Database.Schema;
using JoshOlson.Shared.Extensions;

namespace JoshOlson.Database.Locks;

// `migrations/schema.lock.yaml`: the migration the seeds were last migrated to, the migrations that led there, and
// the columns they produced. Generated by the tool and never edited by hand (ADR 0034, lock file and branch-safe
// migration). `Version` is the newest migration the seeds were migrated against, which can be older than the newest one
// on disk while the next migration is being perfected.
public sealed record SchemaLock {
  public required int Version { get; init; }
  public required List<LockedMigration> Migrations { get; init; }
  public required List<SchemaComment> Schemas { get; init; }
  public required List<Domain> Domains { get; init; }
  public required List<Table> Tables { get; init; }

  // Compares the migrations on disk to the ones the seeds were migrated against, by version.
  public LockCheck Check(List<MigrationFile> onDisk) {
    var disk = onDisk.ToDictionary(migration => migration.Version);
    List<MigrationProblem> problems = [];

    foreach (var locked in Migrations) {
      var version = locked.Version.ToInvariantString();
      if (!disk.TryGetValue(locked.Version, out var current)) {
        problems.Add(Problem(
          locked.Version,
          MigrationProblemKind.Missing,
          $"The seeds were migrated against {locked.File} (version {version}), which your migrations do not have."));
      } else if (!string.Equals(current.File, locked.File, StringComparison.Ordinal)) {
        problems.Add(Problem(
          locked.Version,
          MigrationProblemKind.Different,
          $"Your version {version} is {current.File}, but the seeds were migrated against {locked.File}. "
          + "Another branch's migration took this number. Rename yours to the next free number, take the main branch's "
          + "seeds/ and migrations/schema.lock.yaml, and run seeds:migrate."));
      } else if (!locked.Matches(current.Checksum)) {
        problems.Add(Problem(
          locked.Version,
          MigrationProblemKind.Changed,
          $"{locked.File} has changed since the seeds were migrated against it. If the change is only a comment or "
          + $"whitespace, seeds:accept {version} checks that the seeds are unaffected and records it. "
          + "Otherwise add a new migration instead of editing this one."));
      }
    }

    var lockedVersions = Migrations.Select(migration => migration.Version).ToHashSet();
    var seedsVersion = Version.ToInvariantString();
    foreach (var migration in onDisk.Where(migration => migration.Version <= Version && !lockedVersions.Contains(migration.Version))) {
      problems.Add(Problem(
        migration.Version,
        MigrationProblemKind.Unlocked,
        $"Your migrations have {migration.File}, below the seeds' version {seedsVersion}, but the lock has no record of it. "
        + $"A migration cannot be added behind seeds that are already migrated: renumber it above {seedsVersion} and run seeds:migrate."));
    }

    problems.Sort((left, right) => left.Version.CompareTo(right.Version));
    return new() {
      Problems = problems,
      Pending = [.. onDisk.Where(migration => migration.Version > Version).OrderBy(migration => migration.Version)],
    };
  }

  // The lock with one more checksum accepted for the migration, kept in order and without duplicates. The tool calls
  // this only after checking the edit leaves every seed unaffected; the lock itself cannot tell.
  public SchemaLock WithAcceptedChecksum(int version, string checksum) {
    List<LockedMigration> migrations = new(Migrations.Count);
    var found = false;
    foreach (var migration in Migrations) {
      if (migration.Version != version) {
        migrations.Add(migration);
        continue;
      }
      found = true;
      migrations.Add(migration.Matches(checksum)
        ? migration
        : migration with { AcceptedChecksums = [.. migration.AcceptedChecksums.Append(checksum).Order(StringComparer.Ordinal)] });
    }
    return found
      ? this with { Migrations = migrations }
      : throw new SeedFormatException($"The lock has no migration with version {version.ToInvariantString()}.");
  }

  // The tables in an order rows can be inserted in: each one after every table its foreign keys point at, ties broken by
  // name so the order never changes between runs. A table's reference to itself, and a key that is initially deferred
  // (checked only when the transaction ends), do not constrain the order. Mutually referencing tables with no deferred
  // key between them cannot be loaded at all, and that is an error naming them.
  public List<Table> InsertOrder() {
    var known = Tables.Select(table => table.Name).ToHashSet(StringComparer.Ordinal);
    var dependencies = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
    foreach (var table in Tables) {
      var parents = new HashSet<string>(StringComparer.Ordinal);
      foreach (var key in table.ForeignKeys.Where(key => !key.InitiallyDeferred && !string.Equals(key.ReferencedTable, table.Name, StringComparison.Ordinal))) {
        if (!known.Contains(key.ReferencedTable)) {
          throw new SeedFormatException($"{table.Name} foreign key {key.Name} references {key.ReferencedTable}, which is not in the lock.");
        }
        parents.Add(key.ReferencedTable);
      }
      dependencies[table.Name] = parents;
    }

    List<Table> ordered = new(Tables.Count);
    HashSet<string> placed = new(StringComparer.Ordinal);
    var remaining = Tables.OrderBy(table => table.Name, StringComparer.Ordinal).ToList();
    while (remaining.Count > 0) {
      var next = remaining.FirstOrDefault(table => dependencies[table.Name].All(placed.Contains))
        ?? throw new SeedFormatException(
          $"These tables reference each other, and no deferred foreign key breaks the loop, so rows cannot be inserted: {string.Join(", ", remaining.Select(table => table.Name))}.");
      ordered.Add(next);
      placed.Add(next.Name);
      remaining.Remove(next);
    }
    return ordered;
  }

  // The reverse of the insert order: each table before the tables its foreign keys point at.
  public List<Table> DeleteOrder() {
    var ordered = InsertOrder();
    ordered.Reverse();
    return ordered;
  }

  private static MigrationProblem Problem(int version, MigrationProblemKind kind, string message)
    => new() {
      Version = version,
      Kind = kind,
      Message = message,
    };
}
